/**
 * =============================================================================
 *  analyticsService.ts — Platform Analytics Aggregation Service (Phase 2.6)
 * =============================================================================
 *
 * Purpose:
 *   Central service for all admin dashboard analytics aggregation.
 *   Uses MongoDB aggregation pipelines for performance and accuracy.
 *
 * Principles:
 *   - All aggregation happens on the database side
 *   - No loading large datasets into memory
 *   - No frontend reduce/calculate logic
 *   - Every metric is generated by backend aggregation
 *   - Reuses existing models and architecture
 */

import mongoose from 'mongoose';
import Restaurant from '../models/Restaurant';
import User from '../models/User';
import Device from '../models/Device';
import Subscription, { SubscriptionStatus } from '../models/Subscription';

// NOTE: 'cancelled'/'expired' are NOT valid SubscriptionStatus values (schema
// enum: trial | active | grace | suspended). This churn metric therefore
// currently always reads 0. Flagged for owner review — the cast below only
// makes the filter typecheck; it does not change runtime behavior.
import AuditLog from '../models/AuditLog';
import AIUsageLog from '../models/AIUsageLog';
import VoiceAuditLog from '../modules/voice-inventory/models/VoiceAuditLog';
import Payment from '../models/Payment';

