// ─── Subscription Revenue ─────────────────────────────────────

export async function getSubscriptionRevenue(
  startDateParam?: string,
  endDateParam?: string
): Promise<RevenueMetrics> {
  const now = new Date();
  let startDate: Date;
  let endDate: Date;

  if (startDateParam) {
    startDate = new Date(startDateParam);
    if (isNaN(startDate.getTime())) startDate = new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
  } else {
    startDate = new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
  }

  if (endDateParam) {
    endDate = new Date(endDateParam);
    if (isNaN(endDate.getTime())) endDate = now;
    endDate.setHours(23, 59, 59, 999);
  } else {
    endDate = now;
  }

  const dateFilter = { $gte: startDate, $lte: endDate };

  // Aggregate by gateway
  const gatewayAgg = await Payment.aggregate([
    { $match: { status: 'success', createdAt: dateFilter } },
    {
      $group: {
        _id: { $cond: [{ $in: ['$gateway', ['cash', 'manual']] }, 'cash', 'razorpay'] },
        revenue: { $sum: '$amount' },
        count: { $sum: 1 },
      },
    },
  ]).exec();

  const cashData = gatewayAgg.find((r: any) => r._id === 'cash');
  const razorpayData = gatewayAgg.find((r: any) => r._id === 'razorpay');
  const cashRevenue = cashData?.revenue || 0;
  const cashCount = cashData?.count || 0;
  const razorpayRevenue = razorpayData?.revenue || 0;
  const razorpayCount = razorpayData?.count || 0;
  const totalRevenue = cashRevenue + razorpayRevenue;
  const totalCount = cashCount + razorpayCount;

  // Monthly breakdown
  const monthlyData = await Payment.aggregate([
    { $match: { status: 'success', createdAt: dateFilter } },
    {
      $group: {
        _id: {
          month: { $dateToString: { format: '%Y-%m', date: '$createdAt' } },
          isCash: { $in: ['$gateway', ['cash', 'manual']] },
        },
        revenue: { $sum: '$amount' },
        count: { $sum: 1 },
      },
    },
    { $sort: { '_id.month': 1 } },
  ]).exec();

  const monthlyMap: Record<string, { cash: number; razorpay: number; cashCount: number; razorpayCount: number }> = {};
  monthlyData.forEach((r: any) => {
    if (!monthlyMap[r._id.month]) {
      monthlyMap[r._id.month] = { cash: 0, razorpay: 0, cashCount: 0, razorpayCount: 0 };
    }
    if (r._id.isCash) {
      monthlyMap[r._id.month].cash += r.revenue;
      monthlyMap[r._id.month].cashCount += r.count;
    } else {
      monthlyMap[r._id.month].razorpay += r.revenue;
      monthlyMap[r._id.month].razorpayCount += r.count;
    }
  });

  const monthly = Object.entries(monthlyMap)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([month, data]) => ({
      month, cash: data.cash, razorpay: data.razorpay,
      cashCount: data.cashCount, razorpayCount: data.razorpayCount,
      total: data.cash + data.razorpay,
    }));

  // Recent payments
  const recentPayments = await Payment.find({ status: 'success', createdAt: dateFilter } as any)
    .sort({ createdAt: -1 }).limit(20).lean().exec() as any[];

  const recent = recentPayments.map((p) => ({
    id: p._id.toString(),
    invoiceNumber: p.invoiceNumber || '',
    amount: p.amount,
    gateway: p.gateway,
    paymentMethod: p.paymentMethod || p.gateway,
    createdAt: p.createdAt?.toISOString?.() || String(p.createdAt),
  }));

  return {
    total: { revenue: totalRevenue, count: totalCount },
    cash: { revenue: cashRevenue, count: cashCount, percentage: totalRevenue > 0 ? Math.round((cashRevenue / totalRevenue) * 100) : 0 },
    razorpay: { revenue: razorpayRevenue, count: razorpayCount, percentage: totalRevenue > 0 ? Math.round((razorpayRevenue / totalRevenue) * 100) : 0 },
    monthly,
    daily: [],
    weekly: [],
    yearly: [],
    byPaymentMethod: [
      { name: 'Cash / Manual', value: cashRevenue },
      { name: 'Razorpay Online', value: razorpayRevenue },
    ],
    recent,
  };
}

// ─── API Request Analytics ────────────────────────────────────

export async function getApiRequestAnalytics(days: number = 30): Promise<ApiRequestAnalytics> {
  const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000);

  const totalRequests = await AuditLog.countDocuments({ createdAt: { $gte: since } }).exec();

  const perEndpoint = await AuditLog.aggregate([
    { $match: { createdAt: { $gte: since } } },
    { $group: { _id: '$action', count: { $sum: 1 } } },
    { $sort: { count: -1 } },
    { $limit: 20 },
  ]).exec();

  const errorCount = await AuditLog.countDocuments({
    createdAt: { $gte: since },
    action: { $regex: /ERROR|FAIL|DENIED|REJECTED/i },
  }).exec();

  const successRate = totalRequests > 0 ? Math.round(((totalRequests - errorCount) / totalRequests) * 100) : 0;
  const errorRate = totalRequests > 0 ? Math.round((errorCount / totalRequests) * 100) : 0;

  const latencyStats = await AIUsageLog.aggregate([
    { $match: { createdAt: { $gte: since } } },
    { $group: { _id: null, avg: { $avg: '$latencyMs' }, count: { $sum: 1 } } },
  ]).exec();

  const averageLatency = latencyStats.length > 0 ? Math.round(latencyStats[0].avg) : 0;

  const dailyData = await AuditLog.aggregate([
    { $match: { createdAt: { $gte: since } } },
    { $group: { _id: { $dateToString: { format: '%Y-%m-%d', date: '$createdAt' } }, count: { $sum: 1 } } },
    { $sort: { _id: 1 } },
  ]).exec();

  const dailyMap = new Map(dailyData.map((r: any) => [r._id, r.count]));
  const daysArr = getDaysArray(days);
  const daily = daysArr.map((d) => ({ name: d, value: dailyMap.get(d) || 0 }));

  return {
    totalRequests,
    requestsPerEndpoint: perEndpoint.map((r: any) => ({ endpoint: r._id, count: r.count })),
    successRate,
    errorRate,
    averageLatency,
    slowEndpoints: [],
    daily,
  };
}
